def majority_color(grid):
    """The most frequent cell color."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def minority_color(grid):
    """The least frequent cell color."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common()[-1][0]

def fill_between(grid, fg, fill):
    """Cells strictly between two consecutive fg cells in the same row become fill."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        idx = [j for j in range(w) if grid[i][j] == fg]
        for a, b in zip(idx, idx[1:]):
            for j in range(a + 1, b):
                out[i][j] = fill
    return out

from lib import minority_color, fill_between

def transform(grid):
